mapper.select:
SELECT shopion.tOprNotice.*
FROM shopion.tOprNotice

INNER JOIN shopwizard.tCmpChnl ON shopwizard.tCmpChnl.ChnlCode = shopion.tOprNotice.ChnlCode



    ORDER BY shopion.tOprNotice.${sidx} ${sord}
    ORDER BY NoticeNo DESC

LIMIT #{topCnt}, #{countPerPage}

SELECT * FROM shopion.tOprNotice

    AND ChnlCode = #{pChnlCode}
    AND ( CompCode = #{pCompCode} OR CompCode IS NULL OR CompCode = '' )
    AND NoticeNo = #{pNoticeNo}
    AND RegistName LIKE CONCAT('%',#{pRegistName},'%')
    AND NoticeTitle LIKE CONCAT('%',#{pNoticeTitle},'%')
    AND NoticeCntnts LIKE CONCAT('%',#{pNoticeCntnts},'%')

        AND ( ( RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) OR ( NOW() >= StartDate AND NOW() < ADDDATE(EndDate, INTERVAL 1 DAY) ) )


        AND ( NOW() BETWEEN StartDate AND date_add(EndDate,interval+1 day) )



    ORDER BY ${sidx} ${sord}
    ORDER BY NoticeNo DESC

LIMIT #{topCnt}, #{countPerPage}
